const battingCoordinateLookup = battingCoordinates.reduce((map, entry) => {
    map[entry.point] = { zone: entry.zone, foul: entry.foul };
    return map;
}, {});

export const getBattingFieldInfoFromCoordinate = (field_mark) => {
    if (!field_mark || field_mark < 1 || field_mark > 6400) {
        return { direction: null, foul: false };
    }
    const hit = battingCoordinateLookup[field_mark];
    if (!hit) {
        // Use yIndex (horizontal position on screen) for zone, not xIndex (vertical depth)
        const y = Math.ceil(field_mark / 80); // yIndex 1..80
        let direction = null;
        if (y <= 31) direction = 'LF';
        else if (y >= 50) direction = 'RF';
        else direction = 'CF';
        return { direction, foul: false };
    }
    return { direction: hit.zone, foul: !!hit.foul };
};

export const isValidBattingCoordinate = (field_mark) => {
    return field_mark && field_mark >= 1 && field_mark <= 6400;
};

// Grid constants and side bounds for the 80x80 field image
export const FIELD_GRID_WIDTH = 80;
export const FIELD_GRID_HEIGHT = 80;

// Column-based bounds used when a point isn't present in the dataset
export const FIELD_ZONE_BOUNDS = {
    LF: { xStart: 1, xEnd: 30 },
    CF: { xStart: 31, xEnd: 50 },
    RF: { xStart: 51, xEnd: 80 },
};

// Helper to derive grid coordinates from a field_mark (1..6400)
export const getXYFromFieldMark = (field_mark) => {
    if (!isValidBattingCoordinate(field_mark)) return { xIndex: null, yIndex: null };
    const xIndex = ((field_mark - 1) % FIELD_GRID_WIDTH) + 1; // 1..80
    const yIndex = Math.ceil(field_mark / FIELD_GRID_WIDTH);  // 1..80
    return { xIndex, yIndex };
};

// Helper to get LF/CF/RF using dataset first, then fallback bounds.
// Zones are determined by the HORIZONTAL position (yIndex → left on screen),
// NOT the vertical/depth position (xIndex → top on screen).
// Dataset covers xIndex 40-79; fallback handles the rest using yIndex thresholds
// derived from the dataset boundaries: LF ≤ 31, CF 32-49, RF ≥ 50.
export const getZoneFromFieldMark = (field_mark) => {
    if (!isValidBattingCoordinate(field_mark)) return null;
    const hit = battingCoordinateLookup[field_mark];
    if (hit && hit.zone) return hit.zone; // dataset-provided

    // Fallback: use yIndex (horizontal left-right position) for zone
    const { yIndex } = getXYFromFieldMark(field_mark);
    if (yIndex == null) return null;
    if (yIndex <= 31) return 'LF';
    if (yIndex >= 50) return 'RF';
    return 'CF';
};
